INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','easy','mcq','Which HLA haplotypes confer the greatest susceptibility to Type 1 diabetes mellitus?','["A. HLA-DR3 and HLA-DR4","B. HLA-DR1 and HLA-DR2","C. HLA-B27 and HLA-B51","D. HLA-A2 and HLA-A24"]','A','HLA-DR3 and HLA-DR4 (and their associated DQ alleles) account for approximately 90% of genetic susceptibility to T1DM. These MHC class II molecules present beta-cell autoantigens to CD4+ T cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','mcq','In Type 1 diabetes mellitus, the predominant mechanism of beta-cell destruction is:','["A. Amyloid deposition in islets","B. CD8+ cytotoxic T lymphocyte-mediated killing","C. Glucotoxicity from chronic hyperglycaemia","D. Antibody-dependent complement lysis"]','B','CD8+ cytotoxic T lymphocytes are the primary effectors of beta-cell destruction in T1DM. They recognise beta-cell autoantigens (insulin, GAD65, IA-2) presented on MHC class I molecules.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','mcq','Which autoantibody is most specific for Type 1 diabetes mellitus and targets a pancreatic enzyme?','["A. Anti-insulin antibody (IAA)","B. Islet cell antibody (ICA)","C. Anti-glutamic acid decarboxylase antibody (GAD65)","D. Anti-IA-2 antibody"]','C','GAD65 (glutamic acid decarboxylase) antibodies are highly specific for T1DM and found in ~70-80% of newly diagnosed patients. GAD65 is an enzyme expressed in beta cells that catalyses GABA synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','hard','mcq','The histological lesion characteristic of active Type 1 diabetes mellitus is:','["A. Islet amyloid polypeptide deposits","B. Insulitis — lymphocytic infiltration of islets","C. Hydropic degeneration of beta cells","D. Fibrosis and hyalinisation of islets"]','D','Insulitis is the hallmark histological lesion of T1DM. It consists of a predominantly CD8+ T-cell (with some CD4+ and macrophage) infiltrate within the islets. It is seen early in disease and resolves as beta cells are destroyed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','easy','mcq','Diabetic ketoacidosis (DKA) in Type 1 diabetes results primarily from:','["A. Absolute insulin deficiency leading to unchecked lipolysis and ketogenesis","B. Relative insulin resistance in peripheral tissues","C. Excess glucagon-independent hepatic glucose output","D. Renal tubular bicarbonate wasting"]','A','Absolute insulin deficiency in T1DM removes inhibition on hormone-sensitive lipase, causing massive lipolysis. Free fatty acids flood the liver and are converted to ketone bodies (acetoacetate, beta-hydroxybutyrate) faster than they can be metabolised, causing high-anion-gap metabolic acidosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','mcq','Which cytokine produced by infiltrating macrophages is most directly cytotoxic to beta cells in T1DM?','["A. IL-4","B. IL-10","C. IL-1 and TNF-alpha","D. IL-13"]','B','IL-1 and TNF-alpha secreted by activated macrophages induce nitric oxide synthase in beta cells, generating toxic levels of nitric oxide that damage beta-cell DNA and mitochondria. IFN-gamma (from T cells) also contributes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','mcq','Concordance for Type 1 diabetes in identical twins is approximately:','["A. 95-100%","B. 70-80%","C. 35-50%","D. 10-15%"]','C','Concordance in monozygotic twins for T1DM is only ~35-50%, indicating that environmental triggers (viral infections, gut microbiome, early diet) are critical alongside genetic predisposition. This is lower than T2DM concordance (~70-80%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','hard','mcq','The stage of T1DM characterised by normoglycaemia but presence of multiple autoantibodies is:','["A. Stage 3","B. Stage 2","C. Stage 1","D. Pre-stage"]','D','According to the American Diabetes Association staging: Stage 1 = autoantibody positivity + normoglycaemia + normal glucose tolerance; Stage 2 = autoantibodies + dysglycaemia; Stage 3 = overt clinical T1DM with symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','medium','mcq','Which viral infection has been most strongly epidemiologically linked to triggering Type 1 diabetes through molecular mimicry?','["A. Influenza A","B. Coxsackievirus B4","C. Cytomegalovirus","D. Epstein-Barr virus"]','A','Coxsackievirus B4 has the strongest epidemiological and experimental link to T1DM. Molecular mimicry between viral capsid protein VP1 and GAD65 may trigger autoimmune responses. The virus can also directly infect beta cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 1','easy','mcq','On electron microscopy of beta cells early in T1DM pathogenesis, which finding is expected?','["A. Increased dense-core secretory granules","B. Mitochondrial swelling and loss of secretory granules","C. Amyloid fibrils within the rough ER","D. Lipid droplet accumulation"]','B','Early beta-cell stress in T1DM shows ER stress with mitochondrial swelling and progressive depletion of insulin-containing dense-core secretory granules. As destruction progresses, ghost cells (empty cytoplasm) remain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','easy','mcq','The primary defect initiating the pathogenesis of Type 2 diabetes mellitus is:','["A. Autoimmune destruction of beta cells","B. Peripheral insulin resistance in muscle and adipose tissue","C. Pancreatic exocrine insufficiency","D. Deficiency of glucagon-like peptide-1 receptors"]','A','Peripheral insulin resistance (in skeletal muscle, adipose tissue, and liver) is the initiating defect in T2DM. Beta-cell compensation through hypersecretion initially maintains euglycaemia, but eventual beta-cell failure leads to overt diabetes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','mcq','Islet amyloid polypeptide (IAPP/amylin) deposits in T2DM are derived from which cell type?','["A. Alpha cells","B. Delta cells","C. Beta cells","D. PP cells"]','B','IAPP (islet amyloid polypeptide/amylin) is co-secreted with insulin by beta cells. In T2DM, misfolded IAPP forms amyloid fibrils that deposit in and around islets, contributing to beta-cell toxicity. This is visible as amyloid on H&E staining with Congo red confirmation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','mcq','Which interleukin, secreted by adipose tissue macrophages in obesity, drives hepatic insulin resistance?','["A. IL-4","B. IL-10","C. IL-1 beta and TNF-alpha","D. IL-13"]','C','Adipose tissue inflammation in obesity activates M1 macrophages that secrete IL-1 beta, TNF-alpha, and IL-6. These cytokines activate IKK-beta/NF-kB and JNK pathways in hepatocytes, causing serine phosphorylation of IRS-1 and inhibiting insulin signalling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','hard','mcq','The histological hallmark of Type 2 diabetes in the pancreas, seen in >90% of cases, is:','["A. Insulitis","B. Islet hypertrophy","C. Amyloid deposition in islets (IAPP)","D. Ductal metaplasia"]','D','Amyloid deposition derived from IAPP is the characteristic morphological finding in T2DM pancreas, seen in >90% of cases. Congo red staining shows apple-green birefringence. Insulitis is absent (distinguishing from T1DM).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','easy','mcq','Which transcription factor mutation causes maturity-onset diabetes of the young (MODY-3), the most common form of MODY?','["A. IPF-1 (PDX-1)","B. HNF-1 alpha","C. GCK (glucokinase)","D. HNF-4 alpha"]','A','MODY-3 (the most common MODY) is caused by mutations in HNF-1 alpha (hepatocyte nuclear factor-1 alpha). HNF-1 alpha is a transcription factor essential for beta-cell function and glucose-stimulated insulin secretion. MODY-2 is caused by glucokinase mutations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','mcq','Lipotoxicity in Type 2 diabetes beta-cell failure is mediated primarily by:','["A. Free fatty acid-induced ceramide synthesis and ER stress in beta cells","B. Lipoprotein oxidation damaging islet vasculature","C. Cholesterol crystal formation within beta cells","D. Triglyceride accumulation in hepatocytes redirecting portal glucose"]','B','Elevated free fatty acids cause ceramide synthesis (via de novo pathway) and ER stress in beta cells. This activates the unfolded protein response (UPR) and eventually apoptosis. FFA also uncouple mitochondrial oxidative phosphorylation in beta cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','mcq','The metabolic syndrome (WHO criteria) includes all EXCEPT:','["A. Central obesity","B. Hypertriglyceridaemia","C. Low HDL cholesterol","D. Elevated serum ferritin"]','C','The metabolic syndrome criteria include: central obesity (waist circumference), hypertriglyceridaemia, low HDL, hypertension, and impaired fasting glucose. Elevated serum ferritin is NOT a component, though it may be associated with insulin resistance in hereditary haemochromatosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','hard','mcq','In T2DM, the incretin effect is impaired primarily due to reduced secretion of which hormone?','["A. Gastrin","B. Glucagon-like peptide-1 (GLP-1)","C. Peptide YY","D. Ghrelin"]','D','The incretin effect (augmentation of insulin secretion by gut hormones after oral glucose) is markedly impaired in T2DM due to reduced GLP-1 secretion from intestinal L-cells. GLP-1 normally potentiates glucose-stimulated insulin secretion and inhibits glucagon.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','medium','mcq','Which gene variant is the strongest common genetic risk factor for Type 2 diabetes in genome-wide association studies?','["A. PPARG (Pro12Ala variant)","B. TCF7L2","C. KCNJ11 (E23K variant)","D. IRS-1"]','A','TCF7L2 (transcription factor 7-like 2) variants confer the greatest T2DM risk (~1.4-fold per allele) in GWAS. TCF7L2 is involved in Wnt signalling, which regulates GLP-1 secretion and beta-cell proliferation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetes Mellitus Type 2','easy','mcq','The Randle cycle in T2DM pathophysiology refers to:','["A. Futile cycling between glycolysis and gluconeogenesis in the liver","B. Competition between fatty acid and glucose oxidation in skeletal muscle","C. Beta-cell cycling between insulin synthesis and secretion","D. Oscillatory glucose-stimulated insulin secretion"]','B','The Randle (glucose-fatty acid) cycle describes competition between FFA and glucose for oxidation in skeletal muscle. Elevated circulating FFAs in obesity preferentially oxidise in muscle, inhibiting pyruvate dehydrogenase and phosphofructokinase, thereby reducing glucose uptake and oxidation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','easy','mcq','The earliest morphological change in diabetic nephropathy is:','["A. Nodular glomerulosclerosis (Kimmelstiel-Wilson lesion)","B. Diffuse glomerular basement membrane thickening and mesangial expansion","C. Tubular hyalinosis","D. Interstitial fibrosis"]','A','The earliest morphological changes in diabetic nephropathy are GBM thickening and mesangial matrix expansion, detectable within 2-5 years of onset. Nodular (Kimmelstiel-Wilson) lesions are pathognomonic but appear later. These changes are driven by non-enzymatic glycosylation of GBM proteins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','mcq','Kimmelstiel-Wilson nodules in diabetic nephropathy are composed of:','["A. Amyloid fibrils derived from immunoglobulin light chains","B. Laminated deposits of mesangial matrix proteins in a nodular arrangement","C. Fibrin thrombi within glomerular capillaries","D. Calcium phosphate deposits in the mesangium"]','B','Kimmelstiel-Wilson nodules are PAS-positive, laminated accumulations of mesangial matrix (collagen IV, fibronectin, laminin) in a nodular pattern at the periphery of glomeruli. They are pathognomonic for diabetic nephropathy and represent focal advanced mesangial expansion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','mcq','Background diabetic retinopathy is characterised by all of the following EXCEPT:','["A. Microaneurysms","B. Hard exudates","C. Flame haemorrhages","D. New vessel formation (neovascularisation)"]','C','Neovascularisation (new vessel formation) is a feature of PROLIFERATIVE (advanced) diabetic retinopathy, not background (non-proliferative) retinopathy. Background DR includes: microaneurysms (earliest sign), dot-blot haemorrhages, hard exudates, soft exudates (cotton-wool spots).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','hard','mcq','The pathological mechanism driving neovascularisation in proliferative diabetic retinopathy is:','["A. Overexpression of VEGF by ischaemic retinal cells","B. Autoimmune attack on retinal endothelium","C. Pericyte proliferation stimulated by hyperglycaemia","D. Lipid deposition in retinal blood vessel walls"]','D','Retinal ischaemia (caused by capillary occlusion, pericyte loss, and basement membrane thickening) triggers VEGF (vascular endothelial growth factor) overexpression by hypoxic Muller cells and retinal pigment epithelium. VEGF drives neovascularisation, the hallmark of proliferative DR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','easy','mcq','Diabetic peripheral neuropathy is predominantly a:','["A. Demyelinating neuropathy affecting large myelinated fibres first","B. Symmetrical distal sensorimotor polyneuropathy (''dying-back'' axonopathy)","C. Mononeuropathy multiplex due to nerve infarcts","D. Pure motor neuropathy sparing sensory modalities"]','A','Diabetic peripheral neuropathy is characteristically a length-dependent, symmetrical distal sensorimotor polyneuropathy with a ''dying-back'' pattern (distal axonal degeneration). Both myelinated (large) and unmyelinated (small) fibres are affected. Pathologically: axonal degeneration, segmental demyelination, and endoneurial vessel thickening.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','mcq','The key biochemical pathway linking hyperglycaemia to pericyte loss in diabetic retinopathy is:','["A. Sorbitol accumulation via the polyol pathway","B. Advanced glycation end-product (AGE) formation","C. Activation of protein kinase C (PKC) beta","D. All of the above pathways contribute"]','B','Multiple biochemical pathways operate simultaneously in diabetic vascular complications: (1) Polyol pathway — sorbitol accumulation; (2) AGE formation — cross-linking and receptor activation (RAGE); (3) PKC beta activation — increasing VEGF, altering vascular permeability; (4) Hexosamine pathway. All contribute to pericyte loss and capillary dropout.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','mcq','A diabetic patient''''s renal biopsy shows hyaline deposits in afferent AND efferent arterioles. This pattern is most characteristic of:','["A. Hypertensive nephrosclerosis","B. Diabetic nephropathy","C. Amyloidosis","D. MPGN"]','C','Hyaline arteriolosclerosis affecting BOTH afferent AND efferent arterioles is pathognomonic of diabetic nephropathy. In hypertensive nephrosclerosis, only the afferent arteriole is typically affected. The hyaline represents plasma protein insudation into arteriolar walls due to endothelial injury.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','hard','mcq','Charcot neuroarthropathy (neuropathic joint) in diabetes most commonly affects the:','["A. Hip joint","B. Knee joint","C. Ankle and tarsal joints","D. Cervical spine"]','D','Charcot neuroarthropathy most commonly affects the ankle and tarsal joints (midfoot) in diabetic patients. Loss of pain sensation (from peripheral neuropathy) leads to repeated unperceived microtrauma, eventually causing joint destruction, bony fragmentation, and deformity. Pathologically shows osteoclastic bone resorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','medium','mcq','The ''onion-skin'' thickening of arteriolar walls in diabetes is due to:','["A. Concentric smooth muscle hyperplasia","B. Basement membrane reduplication and pericyte loss","C. Fibrin deposition in the media","D. Mucopolysaccharide accumulation in the intima"]','A','Diabetic microangiopathy characteristically shows basement membrane thickening (PAS-positive), pericyte loss, and reduplication of the capillary basement membrane. On electron microscopy, this appears as multilayered (''onion-skin'') BM. This affects capillaries throughout the body (retina, kidney, nerve, skin).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Diabetic Complications','easy','mcq','Microalbuminuria in diabetic nephropathy is defined as urinary albumin excretion of:','["A. >300 mg/day","B. 30-300 mg/day","C. 3-30 mg/day","D. <3 mg/day"]','B','Microalbuminuria is defined as urinary albumin excretion of 30-300 mg/day (20-200 micg/min). It is the earliest clinical marker of diabetic nephropathy and indicates GBM damage with loss of the negative charge barrier. Values >300 mg/day = macroalbuminuria (overt proteinuria).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','easy','mcq','Hashimoto thyroiditis is characterised by autoantibodies directed against:','["A. TSH receptor","B. Thyroid peroxidase (TPO) and thyroglobulin","C. Thyroid stimulating immunoglobulin (TSI)","D. T3/T4 receptor on target tissues"]','A','Anti-TPO (anti-microsomal) antibodies are present in >90% of Hashimoto thyroiditis cases; anti-thyroglobulin antibodies are also elevated. These are the diagnostic autoantibodies. TSH receptor antibodies (stimulating) are characteristic of Graves disease, not Hashimoto.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','mcq','The morphological hallmark of Hashimoto thyroiditis on histology is:','["A. Diffuse follicular hyperplasia with tall columnar epithelium","B. Lymphocytic infiltration with germinal centre formation and Hurthle cell change","C. Psammoma bodies within follicles","D. Amyloid deposition in the stroma"]','B','Hashimoto thyroiditis shows: (1) extensive lymphocytic infiltration with germinal centre formation, (2) Hurthle (oxyphilic) cell metaplasia of follicular epithelium — enlarged cells with abundant granular eosinophilic cytoplasm due to mitochondrial accumulation, (3) follicular atrophy and fibrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','mcq','Cretinism (congenital hypothyroidism) results from severe iodine deficiency and manifests with:','["A. Thyroid enlargement only, with normal neurological development","B. Severe intellectual disability, short stature, deaf-mutism, and spastic diplegia","C. Exophthalmos and tachycardia","D. Accelerated bone age"]','C','Congenital hypothyroidism (cretinism) causes: severe intellectual disability (irreversible brain damage from lack of T3 during development), growth retardation/dwarfism, deaf-mutism, coarse facies, macroglossia, umbilical hernia, and spastic diplegia. Early neonatal screening and treatment prevent permanent neurological damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','hard','mcq','Myxoedema in severe hypothyroidism is due to accumulation of which substance in the dermis?','["A. Amyloid fibrils","B. Glycosaminoglycans (hyaluronic acid and chondroitin sulphate)","C. Lipofuscin granules","D. Cholesterol crystals"]','D','Myxoedema results from dermal accumulation of glycosaminoglycans (hyaluronic acid and chondroitin sulphate). Without adequate T3/T4, turnover of GAGs is impaired. The hydrophilic GAGs bind water, causing non-pitting, doughy oedema. This is distinct from pitting oedema (transudates) and localised myxoedema of Graves.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','easy','mcq','Riedel thyroiditis is characterised by:','["A. Granulomatous inflammation with giant cells","B. Dense fibrous replacement of thyroid and extension into adjacent neck structures","C. Neutrophilic abscess formation","D. Lymphocytic infiltration with preserved architecture"]','A','Riedel thyroiditis is a rare fibrosing thyroiditis characterised by dense, rock-hard fibrosis replacing the thyroid and extending into adjacent structures (trachea, oesophagus, carotid sheaths). It is part of the IgG4-related disease spectrum. Presents as a fixed, hard thyroid mass mimicking carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','mcq','In hypothyroidism, the biochemical finding of elevated TSH with low free T4 indicates:','["A. Secondary hypothyroidism (pituitary failure)","B. Primary hypothyroidism (thyroid gland failure)","C. Tertiary hypothyroidism (hypothalamic failure)","D. Sick euthyroid syndrome"]','B','Elevated TSH + low free T4 = primary hypothyroidism (thyroid gland failure). The pituitary senses low T4 and increases TSH secretion (intact feedback). In secondary hypothyroidism (pituitary failure), both TSH and T4 are low. In tertiary (hypothalamic), TRH is deficient.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','mcq','Subacute (de Quervain) granulomatous thyroiditis is caused by:','["A. Autoimmune destruction mediated by anti-TPO antibodies","B. Viral infection (commonly mumps, influenza, coxsackievirus) with granulomatous reaction","C. IgG4-related fibrosing inflammation","D. Bacterial infection with abscess formation"]','C','Subacute (de Quervain) thyroiditis follows viral upper respiratory tract infection. Granulomatous inflammation with multinucleated giant cells surrounding colloid forms the histological hallmark. It causes transient thyroid pain, elevated ESR, and a triphasic course: hyperthyroid → hypothyroid → euthyroid recovery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','hard','mcq','The hypothyroid patient who develops pericardial effusion has accumulation of which fluid type?','["A. Haemorrhagic exudate","B. Lymphocytic transudates","C. Mucopolysaccharide-rich fluid","D. Fibrinous exudate"]','D','Pericardial effusion in hypothyroidism contains mucopolysaccharide (GAG)-rich fluid — the same material that accumulates in myxoedema of the skin. Overt myxoedema can cause pleural and pericardial effusions in addition to the characteristic non-pitting subcutaneous oedema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','medium','mcq','Which antibody mediates the cytotoxic (type II hypersensitivity) component of Hashimoto thyroiditis?','["A. Anti-TSH receptor blocking antibody","B. Anti-TPO antibody activating complement and ADCC","C. Anti-thyroglobulin IgE antibody","D. Anti-sodium-iodide symporter antibody"]','A','Anti-TPO antibodies in Hashimoto can activate complement (classical pathway) and mediate antibody-dependent cellular cytotoxicity (ADCC) by NK cells — a type II hypersensitivity mechanism. Additionally, T-cell mediated (type IV) mechanisms operate. This dual mechanism explains the irreversible follicular destruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hypothyroidism','easy','mcq','Hashimoto thyroiditis increases the risk of which thyroid malignancy?','["A. Follicular thyroid carcinoma","B. Anaplastic thyroid carcinoma","C. Primary thyroid lymphoma (B-cell)","D. Medullary thyroid carcinoma"]','B','Hashimoto thyroiditis significantly increases the risk of primary thyroid lymphoma, virtually always B-cell type (diffuse large B-cell lymphoma or MALT lymphoma). The chronic lymphocytic infiltration provides the substrate for lymphoid neoplastic transformation. Papillary thyroid carcinoma also has an association.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','easy','mcq','Graves disease is caused by autoantibodies that:','["A. Block TSH receptors causing hypothyroidism","B. Stimulate TSH receptors causing hyperthyroidism (TSH-R stimulating Ab)","C. Destroy thyroid follicular cells via complement","D. Inhibit thyroid peroxidase reducing hormone synthesis"]','A','Graves disease is caused by TSH receptor-stimulating immunoglobulins (TSI/TRAb) — IgG autoantibodies that mimic TSH by binding and chronically stimulating the TSH receptor. This causes unregulated thyroid hormone synthesis, diffuse goitre, and the extrathyroidal manifestations (ophthalmopathy, pretibial myxoedema).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','mcq','The morphological appearance of the thyroid in Graves disease shows:','["A. Pale, colloid-filled follicles with flattened epithelium","B. Diffuse hyperplasia with tall columnar epithelium and peripheral scalloping of colloid","C. Multiple autonomously functioning nodules","D. Lymphocytic infiltration with germinal centres"]','B','Graves thyroid shows: (1) diffuse hyperplasia with tall columnar follicular cells, (2) peripheral scalloping (''Xmas tree'' appearance) of colloid due to rapid resorption, (3) papillary infoldings without true fibrovascular cores, (4) increased vascularity, and (5) lymphocytic infiltrate (reflecting autoimmunity).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','mcq','Papillary thyroid carcinoma (PTC) is characterised histologically by:','["A. Follicular pattern with vascular and capsular invasion","B. Orphan Annie eye nuclei and psammoma bodies","C. Solid sheets of undifferentiated anaplastic cells","D. Parafollicular C-cell origin with amyloid stroma"]','C','PTC histological hallmarks: (1) Orphan Annie eye nuclei — clear, empty-appearing nuclei with longitudinal grooves and pseudoinclusions; (2) Psammoma bodies — laminated calcific concentric spherules; (3) True papillary architecture with fibrovascular cores. Diagnosis is based on nuclear features even in follicular variant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','hard','mcq','The most common oncogenic driver in papillary thyroid carcinoma is:','["A. RAS point mutations","B. RET/PTC rearrangements and BRAF V600E mutation","C. PAX8-PPARG rearrangement","D. TP53 mutation"]','D','BRAF V600E mutation (~45% of PTC) and RET/PTC rearrangements (~20-30%) are the most common genetic alterations in PTC. BRAF V600E is associated with more aggressive behaviour. PAX8-PPARG is characteristic of follicular thyroid carcinoma. TP53 mutations are seen in anaplastic (undifferentiated) carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','easy','mcq','Follicular thyroid carcinoma (FTC) is distinguished from follicular adenoma by:','["A. Nuclear atypia and mitoses","B. Capsular and/or vascular invasion on histology","C. Positive calcitonin immunostain","D. Presence of psammoma bodies"]','A','The ONLY histological criterion distinguishing FTC from follicular adenoma is evidence of capsular penetration and/or vascular invasion. Cytological features (atypia, mitoses) are unreliable. Hence FNA cannot diagnose FTC — it requires surgical excision with thorough capsule sampling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','mcq','Medullary thyroid carcinoma (MTC) arises from parafollicular C-cells and secretes:','["A. Thyroglobulin","B. Calcitonin and CEA","C. Parathyroid hormone-related peptide","D. Thyroid peroxidase"]','B','MTC arises from parafollicular C-cells (neural crest origin) and secretes calcitonin (diagnostic tumour marker) and CEA. Histologically: sheets/nests of polygonal/spindle cells with amyloid stroma (derived from procalcitonin). 25% are hereditary (MEN 2A, MEN 2B, or familial MTC) due to RET proto-oncogene mutations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','mcq','Thyroid storm (thyrotoxic crisis) is a life-threatening complication associated with which triad?','["A. Hyperpyrexia, tachycardia/arrhythmia, and altered mental state","B. Hypotension, bradycardia, and hypothermia","C. Hypocalcaemia, tetany, and stridor","D. Hypoglycaemia, coma, and seizures"]','C','Thyroid storm presents with: hyperpyrexia (>38.5C), severe tachycardia/atrial fibrillation, and neuropsychiatric disturbance (agitation, delirium, coma). It is precipitated by stress (surgery, infection) in uncontrolled hyperthyroidism. Burch-Wartofsky criteria are used for diagnosis. Treatment: propylthiouracil, beta-blockers, iodine (Lugol), dexamethasone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','hard','mcq','Pretibial myxoedema in Graves disease is caused by:','["A. Venous hypertension and lymphatic obstruction","B. TSH receptor stimulation on dermal fibroblasts causing GAG accumulation","C. Anti-TPO antibody deposition in skin","D. Hypothyroidism-related GAG accumulation"]','D','Pretibial myxoedema occurs in Graves disease (a hyperthyroid state, not hypothyroid). TSH receptor-stimulating antibodies activate TSH receptors on dermal fibroblasts in the pretibial skin, causing excessive hyaluronic acid/GAG synthesis. This produces indurated, non-pitting plaques over the shins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','medium','mcq','Anaplastic thyroid carcinoma (undifferentiated carcinoma) characteristically:','["A. Has excellent prognosis with radioiodine treatment","B. Presents in older patients as a rapidly enlarging, fatal neck mass","C. Secretes calcitonin and responds to surgery","D. Shows RET/PTC rearrangements as the primary driver"]','A','Anaplastic thyroid carcinoma is one of the most lethal human malignancies. It occurs in elderly patients and presents as a rapidly enlarging neck mass causing stridor, dysphagia. Histology: pleomorphic giant cells, spindle cells, squamoid cells. TP53 mutations are key. Median survival <6 months. Radioiodine is ineffective.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Thyroid Disease — Hyperthyroidism and Thyroid Cancer','easy','mcq','Which RAS mutation is most commonly found in follicular thyroid carcinoma?','["A. BRAF V600E","B. NRAS codon 61 mutation","C. RET/PTC1 rearrangement","D. TERT promoter mutation"]','B','NRAS codon 61 mutations are the most common oncogenic drivers in follicular thyroid carcinoma (~40-50%), along with PAX8-PPARG rearrangements (~30%). BRAF V600E is characteristic of PTC. TERT promoter mutations occur in more aggressive differentiated thyroid cancers and anaplastic carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','easy','mcq','Cushing syndrome caused by a pituitary ACTH-secreting adenoma is called Cushing''''s disease. The most common overall cause of Cushing syndrome is:','["A. Ectopic ACTH secretion by small cell lung carcinoma","B. Exogenous glucocorticoid administration","C. Adrenal cortical adenoma","D. Adrenal cortical carcinoma"]','A','Exogenous glucocorticoid administration (iatrogenic Cushing syndrome) is the most common cause overall. Among ENDOGENOUS causes: Cushing disease (pituitary ACTH adenoma, ~70%), ectopic ACTH (~15%), adrenal adenoma/carcinoma (~15%). Recognition of iatrogenic cause is clinically critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','mcq','The morphological appearance of the adrenal glands in primary adrenal Cushing syndrome (cortical adenoma) shows:','["A. Bilateral adrenal hyperplasia","B. Unilateral adenoma with contralateral adrenal cortical atrophy","C. Bilateral multinodular hyperplasia","D. Diffuse haemorrhage and necrosis"]','B','In primary adrenal Cushing from a cortical adenoma: the adenoma autonomously secretes cortisol, suppressing ACTH, leading to atrophy of the non-neoplastic cortex in the ipsilateral gland and contralateral adrenal. Bilateral hyperplasia is seen in ACTH-dependent causes (pituitary or ectopic ACTH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','mcq','Primary hyperaldosteronism (Conn syndrome) presents with the triad of:','["A. Hypertension, hypokalaemia, and suppressed plasma renin activity","B. Hypertension, hyperkalaemia, and elevated plasma renin","C. Hypotension, hyperkalaemia, and low aldosterone","D. Hypertension, hypernatraemia, and elevated ACTH"]','C','Conn syndrome (primary hyperaldosteronism): aldosterone-secreting adrenal adenoma (or bilateral hyperplasia) causes: (1) hypertension (sodium and water retention), (2) hypokalaemia (kaluresis), (3) suppressed renin (aldosterone excess directly suppresses renin, unlike secondary hyperaldosteronism). Metabolic alkalosis also occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','hard','mcq','Waterhouse-Friderichsen syndrome is characterised by:','["A. Bilateral adrenal haemorrhage and necrosis in the context of septicaemia (typically meningococcal)","B. Autoimmune destruction of the adrenal cortex","C. Bilateral adrenal cortical hyperplasia from CRH excess","D. Adrenal vein thrombosis due to hypercoagulable state"]','D','Waterhouse-Friderichsen syndrome: bilateral adrenal haemorrhage causing acute adrenocortical insufficiency, classically in meningococcal septicaemia (Neisseria meningitidis). DIC causes widespread microvascular thrombosis. Haemorrhage renders both adrenals non-functional. Presents with shock, purpuric rash, rapidly fatal without treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','easy','mcq','The gross appearance of a cortisol-secreting adrenal cortical adenoma is:','["A. Yellow-orange cut surface due to high lipid content","B. Dark brown nodule due to pigment accumulation","C. White-grey firm nodule with calcification","D. Haemorrhagic cystic lesion"]','A','Cortisol-secreting adrenal adenomas are characteristically yellow-orange on cut surface due to the high lipid content of cortisol-producing clear cells (zona fasciculata phenotype). This lipid represents cholesterol — the precursor for steroidogenesis. Size: typically <50g.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','mcq','In Addison disease (primary adrenocortical insufficiency), the most common cause in developed countries is:','["A. Tuberculosis","B. Autoimmune adrenalitis (lymphocytic infiltration)","C. Bilateral adrenal metastases","D. Histoplasmosis"]','B','In developed countries, autoimmune adrenalitis accounts for ~70-80% of Addison disease. Autoantibodies against 21-hydroxylase (CYP21A2) are diagnostic. Histology shows lymphocytic infiltration with progressive loss of cortical cells, sparing the medulla. In developing countries, TB remains a major cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','mcq','Nelson syndrome occurs when:','["A. An adrenal adenoma continues to grow after bilateral adrenalectomy","B. A pituitary corticotroph adenoma enlarges aggressively after bilateral adrenalectomy for Cushing disease","C. Ectopic ACTH production causes bilateral adrenal hyperplasia","D. MEN1 causes simultaneous pituitary and adrenal adenomas"]','C','Nelson syndrome: bilateral adrenalectomy removes the negative cortisol feedback on the pituitary corticotroph adenoma, causing it to enlarge rapidly and secrete very high ACTH levels. Features: hyperpigmentation (MSH-like activity of ACTH fragments), visual field defects from tumour expansion, high ACTH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','hard','mcq','The zona glomerulosa, zona fasciculata, and zona reticularis of the adrenal cortex produce respectively:','["A. Aldosterone, cortisol, sex steroids","B. Cortisol, aldosterone, sex steroids","C. Sex steroids, cortisol, aldosterone","D. Aldosterone, sex steroids, cortisol"]','D','GFR rule: Glomerulosa = aldosterone (mineralocorticoids); Fasciculata = cortisol (glucocorticoids); Reticularis = sex steroids (androgens/oestrogens). Mnemonic: ''GFR'' from outside in. The medulla (innermost) produces catecholamines from chromaffin cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','medium','mcq','Adrenocortical carcinoma (ACC) is distinguished from adenoma by:','["A. Yellow colour on cut surface","B. Size >100g, necrosis, atypical mitoses, and venous invasion (Weiss criteria)","C. Cortisol secretion","D. Presence of a capsule"]','A','Weiss criteria for adrenocortical carcinoma include: weight >100-200g, diameter >6cm, necrosis, diffuse architecture (>33%), atypical mitoses, >5 mitoses/50HPF, venous/sinusoidal/capsular invasion, clear cells <25%. 3+ criteria = malignant. Benign adenomas are typically <50g, <4cm, with no necrosis or invasion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Cortex Disease','easy','mcq','Congenital adrenal hyperplasia (CAH) most commonly results from deficiency of:','["A. 11-beta-hydroxylase","B. 21-alpha-hydroxylase","C. 17-alpha-hydroxylase","D. 3-beta-hydroxysteroid dehydrogenase"]','B','21-hydroxylase (CYP21A2) deficiency accounts for >90% of CAH cases. It blocks cortisol and aldosterone synthesis while shunting precursors into the androgen pathway. Classic form: salt-wasting (aldosterone and cortisol deficiency) with virilisation. The enzyme converts 17-hydroxyprogesterone to 11-deoxycortisol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','easy','mcq','Phaeochromocytoma arises from which cell type?','["A. Adrenal cortical cells","B. Adrenal medullary chromaffin cells","C. Paraganglionic cells outside the adrenal","D. Adrenal capsule fibroblasts"]','A','Phaeochromocytoma arises from chromaffin cells of the adrenal medulla (neural crest-derived cells). Chromaffin cells are named for their brown colour when stained with chromium salts due to oxidised catecholamines. Extra-adrenal tumours from sympathetic ganglia are called paragangliomas.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','mcq','The ''''rule of 10s'''' for phaeochromocytoma states that 10% are bilateral, 10% are extra-adrenal, and:','["A. 10% are malignant","B. 10% are functional","C. 10% are calcified","D. 10% are associated with hypertension"]','B','The classic rule of 10s: 10% bilateral, 10% extra-adrenal (paraganglioma), 10% malignant, 10% in children, 10% familial (though hereditary cases are now recognised to be up to 25-30% with germline mutations in RET, VHL, NF1, SDH genes).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','mcq','Microscopically, phaeochromocytoma shows a characteristic ''''Zellballen'''' pattern, which refers to:','["A. Palisading of tumour cells around blood vessels","B. Nests of cells surrounded by sustentacular cells and fibrovascular septa","C. Solid sheets of cells with prominent nucleoli","D. Glandular structures with mucin secretion"]','C','Zellballen (German: cell balls) describes the characteristic nested/alveolar architecture of phaeochromocytoma and paraganglioma: clusters/nests of tumour (chief/principal) cells surrounded by sustentacular cells (S100+) and delicate fibrovascular septa. Chief cells stain for chromogranin A and synaptophysin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','hard','mcq','A patient with episodic hypertension, headache, sweating, and palpitations is found to have elevated urinary catecholamines. The most reliable biochemical test for phaeochromocytoma is:','["A. Serum ACTH stimulation test","B. Plasma/urinary fractionated metanephrines","C. Urinary 5-HIAA","D. Serum chromogranin A alone"]','D','Plasma or urinary fractionated metanephrines (metanephrine and normetanephrine — methylated catecholamine metabolites) have the highest sensitivity (>95%) for phaeochromocytoma diagnosis. They are continuously produced within tumour cells regardless of episodic catecholamine secretion, unlike catecholamines themselves.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','easy','mcq','Malignancy in phaeochromocytoma is defined by:','["A. Mitotic rate >5/10HPF","B. Presence of metastases in sites where chromaffin tissue does not normally exist","C. Vascular invasion on histology","D. Tumour necrosis and capsular invasion"]','A','Malignancy in phaeochromocytoma/paraganglioma CANNOT be predicted by histology alone. The only definitive criterion for malignancy is the presence of metastases at sites where chromaffin tissue is not normally present (liver, lung, bone, lymph nodes). The PASS score (Phaeochromocytoma of the Adrenal Gland Scaled Score) attempts histological risk stratification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','mcq','Which genetic syndrome most strongly predisposes to bilateral phaeochromocytomas?','["A. MEN 2B","B. Von Hippel-Lindau (VHL) disease","C. Neurofibromatosis type 1 (NF1)","D. MEN 2A"]','B','VHL disease (VHL gene mutation — chromosome 3p25, E3 ligase component) is associated with bilateral phaeochromocytomas (noradrenergic type), haemangioblastomas, clear cell renal cell carcinoma, and pancreatic cysts. VHL protein regulates HIF-1 alpha degradation; loss leads to VEGF overexpression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','mcq','The gross appearance of a resected phaeochromocytoma typically shows:','["A. A yellow-orange cut surface due to lipid content","B. Grey-white to reddish-brown cut surface with haemorrhage, necrosis, and cystic change","C. A homogeneous tan surface without haemorrhage","D. Calcified white nodule with clear fluid"]','C','Phaeochromocytomas are typically large (>100g), reddish-brown to grey tumours with haemorrhage, cystic change, and focal necrosis. The characteristic brown colour is due to oxidised catecholamines reacting with chromium salts (chromaffin reaction). The cut surface is often variegated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','hard','mcq','Paraganglioma of the head and neck (e.g., carotid body tumour) most commonly involves mutation of:','["A. RET proto-oncogene","B. SDHB or SDHD (succinate dehydrogenase subunit genes)","C. VHL tumour suppressor gene","D. NF1 gene"]','D','Head and neck paragangliomas are most commonly associated with mutations in SDH (succinate dehydrogenase) subunit genes — SDHB, SDHC, SDHD. SDHB mutations are associated with malignant paragangliomas. SDH is complex II of the mitochondrial respiratory chain; mutations cause pseudohypoxia via succinate-mediated HIF-1 alpha stabilisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','medium','mcq','A child with a large retroperitoneal mass arising from the adrenal medulla, showing Homer-Wright pseudorosettes and N-MYC amplification is most likely:','["A. Adrenocortical carcinoma","B. Neuroblastoma","C. Wilms tumour","D. Ganglioneuroma"]','A','Neuroblastoma is the most common extracranial solid tumour of childhood, arising from neural crest-derived neuroblasts in the adrenal medulla or sympathetic ganglia. Homer-Wright pseudorosettes (tumour cells surrounding neuropil), N-MYC amplification (poor prognosis marker), elevated urinary catecholamines (VMA/HVA). Presents as large retroperitoneal mass.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Adrenal Medulla Tumours','easy','mcq','The PASS (Phaeochromocytoma of the Adrenal gland Scaled Score) assigns higher malignant potential to tumours with:','["A. Low cellularity and no mitoses","B. Large nests, diffuse growth, necrosis, atypical mitoses, and high mitotic rate","C. Zellballen pattern with <2 mitoses/10HPF","D. Prominent sustentacular cells (S100+)"]','B','The PASS score (Thompson 2002) assigns points for: large irregular nests/diffuse growth (>2pts each), central or confluent necrosis (2pts), high cellularity (2pts), cellular monotony (2pts), >3 mitoses/10HPF (2pts), atypical mitoses (2pts), extension into adipose (2pts), vascular invasion (1pt), capsular invasion (1pt), nuclear pleomorphism (1pt), nuclear hyperchromasia (1pt). Score ≥4 = potentially malignant.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','easy','mcq','The most common type of pituitary adenoma, accounting for approximately 30% of all pituitary adenomas, is:','["A. GH-secreting somatotroph adenoma","B. ACTH-secreting corticotroph adenoma","C. Prolactin-secreting lactotroph adenoma (prolactinoma)","D. Non-functioning gonadotroph adenoma"]','A','Prolactinomas are the most common pituitary adenomas (~30%). They are usually microadenomas (<10mm) in women (amenorrhoea-galactorrhoea) and macroadenomas in men (impotence, headache). They express prolactin by immunohistochemistry and respond to dopamine agonists (cabergoline/bromocriptine).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','mcq','A macroadenoma of the pituitary compressing the optic chiasm causes:','["A. Homonymous hemianopia","B. Bitemporal hemianopia","C. Central scotoma","D. Monocular blindness"]','B','The optic chiasm lies directly above the pituitary fossa. Upward expansion of a pituitary macroadenoma (>10mm) compresses the crossing nasal fibres of the optic chiasm, causing bitemporal hemianopia (loss of peripheral temporal visual fields bilaterally) — the classic visual field defect of pituitary adenoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','mcq','GH-secreting pituitary adenomas (somatotroph adenomas) are characterised by which mutation in >40% of cases?','["A. RET proto-oncogene activation","B. Activating mutations in GNAS1 (Gs-alpha protein)","C. Loss of MENIN tumour suppressor","D. BRAF V600E"]','C','GNAS1 mutations (gsp oncogene) — activating mutations in the Gs-alpha subunit — are found in >40% of GH-secreting adenomas. Gs-alpha normally couples stimulatory receptors (e.g., GHRH receptor) to adenylyl cyclase. Constitutive activation raises cAMP, stimulating somatotroph proliferation and GH secretion autonomously.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','hard','mcq','Craniopharyngioma arises from remnants of:','["A. Rathke''''s pouch (ectoderm derived from oral cavity)","B. Neuroglial cells of the neurohypophysis","C. Infundibular mesodermal cells","D. Arachnoid cells of the pituitary fossa"]','D','Craniopharyngioma arises from remnants of Rathke''''s pouch (the embryonic ectodermal evagination from the roof of the stomodeum that forms the adenohypophysis). It is the most common suprasellar tumour in children. Two types: adamantinomatous (children, CTNNB1 mutations) and papillary (adults, BRAF V600E).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','easy','mcq','Diabetes insipidus (central/neurogenic) results from deficiency of:','["A. Aldosterone","B. Antidiuretic hormone (ADH/vasopressin)","C. Atrial natriuretic peptide","D. Renin"]','A','Central diabetes insipidus results from inadequate ADH (vasopressin) production/secretion by the posterior pituitary. ADH acts on V2 receptors in collecting ducts, inserting aquaporin-2 channels. Deficiency causes inability to concentrate urine (polyuria of dilute urine), polydipsia, and hypernatraemia if fluid intake is inadequate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','mcq','Acromegaly (excess GH in adults) causes coarsening of facial features, prognathism, and organomegaly. The most dangerous complication is:','["A. Renal stones","B. Cardiomegaly and cardiomyopathy (leading cause of death)","C. Peripheral neuropathy","D. Colorectal polyps"]','B','Cardiomyopathy (acromegalic cardiomyopathy — biventricular hypertrophy and diastolic dysfunction) is the leading cause of death in acromegaly. Other complications: hypertension, sleep apnoea, diabetes (GH is counter-regulatory to insulin), colorectal cancer risk, and carpal tunnel syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','mcq','Sheehan syndrome is post-partum hypopituitarism caused by:','["A. Autoimmune lymphocytic hypophysitis","B. Ischaemic necrosis of the pituitary due to peripartum haemorrhage and hypotension","C. Pituitary macroadenoma compressing normal tissue","D. Sarcoid granulomas in the hypothalamus"]','C','Sheehan syndrome: ischaemic necrosis of the pituitary gland from massive post-partum haemorrhage and hypotension. The pituitary enlarges during pregnancy (lactotroph hyperplasia); increased metabolic demand plus vascular compromise causes selective necrosis of the adenohypophysis. Presents with failure to lactate, amenorrhoea, hypothyroidism, and adrenal insufficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','hard','mcq','The ''''empty sella'''' syndrome radiologically demonstrates a pituitary fossa filled with CSF. The most common cause is:','["A. Pituitary apoplexy","B. Extension of the subarachnoid space through an incompetent diaphragma sellae","C. Complete hypopituitarism","D. Previous pituitary surgery"]','D','Primary empty sella: an incompetent (deficient) diaphragma sellae allows CSF under arterial pulse pressure to herniate into the sella turcica, compressing and flattening the pituitary against the floor. Usually incidental, pituitary function is preserved (the gland is flattened but not destroyed). More common in obese multiparous women.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','medium','mcq','Cushing''''s disease (pituitary ACTH-secreting adenoma) differs from ectopic ACTH syndrome in that:','["A. Cortisol levels are lower in Cushing''''s disease","B. In Cushing''''s disease, high-dose dexamethasone suppresses cortisol; ectopic ACTH is resistant","C. CRH stimulation suppresses ACTH in ectopic syndrome","D. Ectopic ACTH always causes bilateral adrenal hyperplasia but Cushing''''s disease does not"]','A','Biochemical differentiation: in Cushing''''s disease (pituitary corticotroph adenoma), the tumour retains partial CRH responsiveness and partial glucocorticoid feedback. High-dose dexamethasone (8mg) suppresses cortisol by >50%. In ectopic ACTH syndrome (e.g., small cell lung cancer), the tumour is autonomous and resistant to high-dose dexamethasone suppression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Pituitary Disease','easy','mcq','The histological appearance of the normal pituitary anterior lobe shows cells classified as acidophils, basophils, and chromophobes. GH and prolactin cells are:','["A. Basophils","B. Chromophobes","C. Acidophils","D. Both acidophils and basophils equally"]','B','Acidophils (eosinophils) of the pituitary include somatotrophs (GH-secreting) and lactotrophs (prolactin-secreting). Basophils include corticotrophs (ACTH), thyrotrophs (TSH), and gonadotrophs (LH/FSH). Chromophobes have few or no secretory granules and include non-secreting cells and exhausted secretory cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','easy','mcq','The most common cause of primary hyperparathyroidism is:','["A. Parathyroid carcinoma","B. Parathyroid chief cell adenoma (single gland)","C. Four-gland parathyroid hyperplasia","D. Ectopic PTH secretion"]','A','A solitary parathyroid chief cell adenoma accounts for ~80-85% of primary hyperparathyroidism. Chief cells are the PTH-secreting cells. The adenoma is typically encapsulated, with a rim of normal compressed parathyroid tissue. Multiple adenomas (~4%), four-gland hyperplasia (~15%), and carcinoma (<1%) are rarer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','mcq','Osteitis fibrosa cystica (Von Recklinghausen disease of bone) in hyperparathyroidism is characterised by:','["A. Dense osteosclerosis and increased bone density","B. Osteoclastic bone resorption, brown tumours, and subperiosteal resorption of radial aspect of middle phalanges","C. Calcium pyrophosphate deposition in joints","D. Cortical bone thickening with endosteal sclerosis"]','B','Osteitis fibrosa cystica: severe hyperparathyroidism causes osteoclastic bone resorption (PTH activates osteoclasts via RANKL upregulation on osteoblasts). Features: subperiosteal bone resorption (radial aspect of middle phalanges — pathognomonic on X-ray), brown tumours (haemorrhagic osteoclastic giant cell lesions), and bone cysts. Now rare due to early diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','mcq','Secondary hyperparathyroidism in chronic kidney disease results from:','["A. Parathyroid adenoma developing in response to hypocalcaemia","B. Hypocalcaemia (due to phosphate retention and reduced renal 1,25-OH vitamin D) stimulating all four parathyroid glands","C. Ectopic PTH production by renal tubular cells","D. Direct renal tubular loss of PTH"]','C','In CKD: (1) phosphate retention causes hypocalcaemia, (2) reduced 1-alpha-hydroxylase activity decreases 1,25-(OH)2D3 (active vitamin D), further impairing calcium absorption and reducing direct suppression of PTH. Both mechanisms drive compensatory four-gland parathyroid hyperplasia (secondary hyperparathyroidism).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','hard','mcq','Parathyroid carcinoma is distinguished from adenoma by:','["A. Immunostaining for PTH","B. Dense fibrous bands, vascular invasion, and perineural invasion","C. Chief cell cytology","D. Elevated serum calcium levels"]','D','Parathyroid carcinoma shows: dense fibrous bands traversing the tumour (''''band-like'''' fibrosis), capsular invasion, vascular invasion, perineural invasion, and high mitotic rate. Clinically: markedly elevated calcium (usually >14mg/dL) and PTH. Loss of parafibromin (HRPT2/CDC73 gene product) by immunostaining supports diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','easy','mcq','MEN 1 (Wermer syndrome) is caused by mutation of the MENIN gene on chromosome 11q13. The classic triad consists of:','["A. Phaeochromocytoma, MTC, and marfanoid habitus","B. Parathyroid adenoma/hyperplasia, pituitary adenoma, and pancreatic islet tumour","C. Parathyroid hyperplasia, MTC, and phaeochromocytoma","D. Insulinoma, gastrinoma, and glucagonoma"]','A','MEN 1 (MENIN tumour suppressor, chromosome 11q13): Parathyroid hyperplasia/adenoma (>90%, most common and usually first manifestation), Pancreatic islet tumours (gastrinoma most common, also insulinoma, glucagonoma, VIPoma), Pituitary adenoma (prolactinoma most common). Mnemonic: 3 Ps — Parathyroid, Pancreas, Pituitary.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','mcq','Hypercalcaemia in primary hyperparathyroidism can cause nephrocalcinosis. The mechanism involves:','["A. Calcium phosphate precipitation in renal tubules due to high filtered calcium load","B. Immune complex deposition in glomeruli","C. Uric acid crystal deposition causing obstruction","D. Oxalate crystal formation due to vitamin D excess"]','B','Excess PTH causes hypercalcaemia and hypercalciuria. The high filtered calcium load in renal tubules, combined with alkaline urine (PTH causes phosphaturia and bicarbonate loss), promotes calcium phosphate (brushite/hydroxyapatite) precipitation in the collecting ducts and interstitium — nephrocalcinosis. Calcium oxalate stones also form.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','mcq','Hypoparathyroidism most commonly results from:','["A. Autoimmune destruction of parathyroid glands","B. Inadvertent removal or devascularisation during thyroid surgery","C. Infiltration by haemochromatosis","D. DiGeorge syndrome"]','C','The most common cause of hypoparathyroidism is iatrogenic — accidental removal or devascularisation of parathyroid glands during total thyroidectomy, parathyroidectomy, or radical neck dissection. Presents with hypocalcaemia: Chvostek sign (facial muscle twitch), Trousseau sign (carpal spasm with BP cuff), tetany, seizures, and laryngospasm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','hard','mcq','The ''''salt-and-pepper'''' skull on X-ray is a radiological manifestation of:','["A. Paget disease of bone","B. Severe hyperparathyroidism with generalised bone resorption","C. Multiple myeloma","D. Metastatic prostate carcinoma"]','D','''''Salt-and-pepper'''' skull (also called ''''pepper-pot'''' skull) is a radiological sign of primary hyperparathyroidism. It results from demineralisation and granular-appearing bone due to osteoclastic resorption of the calvarium combined with reactive new bone formation, creating alternating lucent and dense spots on skull X-ray.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','medium','mcq','Tertiary hyperparathyroidism occurs when:','["A. Parathyroid hyperplasia in secondary hyperparathyroidism becomes autonomous despite correction of the underlying stimulus","B. A de novo parathyroid adenoma develops in a patient with no prior renal disease","C. Parathyroid carcinoma develops from a pre-existing adenoma","D. MEN 1 mutation causes rapid onset parathyroid adenoma"]','A','Tertiary hyperparathyroidism: prolonged secondary hyperparathyroidism (e.g., in CKD) leads to autonomous PTH secretion from hyperplastic parathyroid glands even after the stimulus (hypocalcaemia) is corrected (e.g., post-renal transplant). PTH and calcium both remain elevated. Parathyroidectomy is required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Parathyroid Disease','easy','mcq','Pseudohypoparathyroidism (Albright hereditary osteodystrophy) is caused by:','["A. Low PTH secretion from absent parathyroid glands","B. End-organ resistance to PTH due to Gs-alpha (GNAS1) loss-of-function mutation","C. Vitamin D receptor mutation preventing calcitriol action","D. Autoantibodies blocking PTH receptors"]','B','Pseudohypoparathyroidism type 1a: inactivating mutations in GNAS1 (Gs-alpha) cause PTH end-organ resistance. PTH is elevated (reactive) but cannot stimulate cAMP in kidney/bone. Features: hypocalcaemia, hyperphosphataemia, elevated PTH, short stature, round facies, short 4th/5th metacarpals, and ectopic calcifications (Albright hereditary osteodystrophy phenotype).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','easy','mcq','Insulinoma is the most common islet cell tumour. The diagnostic biochemical triad (Whipple''''s triad) consists of:','["A. Symptoms of hypoglycaemia, low blood glucose, and relief with glucose administration","B. Elevated insulin, elevated C-peptide, and elevated glucagon","C. Hypoglycaemia, elevated proinsulin, and positive anti-insulin antibodies","D. Fasting hypoglycaemia, hyperinsulinism, and elevated urinary ketones"]','A','Whipple''''s triad: (1) symptoms of hypoglycaemia (fasting or exertional), (2) documented hypoglycaemia (blood glucose <2.2mmol/L), (3) relief of symptoms with glucose administration. Insulinoma is confirmed by elevated insulin and C-peptide (C-peptide excludes exogenous insulin injection, as exogenous insulin lacks C-peptide).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','mcq','Gastrinoma (Zollinger-Ellison syndrome) is characterised by:','["A. Hypoglycaemia and weight gain","B. Recurrent peptic ulcers, diarrhoea, and elevated fasting serum gastrin","C. Necrolytic migratory erythema and hyperglycaemia","D. Profuse watery diarrhoea and achlorhydria"]','B','Zollinger-Ellison syndrome: gastrin-secreting tumour causes: (1) recurrent, multiple, or atypical peptic ulcers (duodenum, jejunum), (2) diarrhoea (gastric acid inactivates pancreatic lipase, damages small bowel mucosa), (3) elevated fasting serum gastrin (>200pg/mL; secretin stimulation test: paradoxical rise in gastrin), (4) gastric acid hypersecretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','mcq','VIPoma (Verner-Morrison syndrome) causes profuse watery diarrhoea due to VIP action on:','["A. Stimulation of intestinal adenylyl cyclase, increasing Cl- secretion and inhibiting Na+ absorption","B. Inhibition of gastric acid secretion via H2 receptor blockade","C. Direct toxin effect on intestinal epithelium","D. Activation of intestinal serotonin receptors"]','C','VIP (vasoactive intestinal peptide) binds VPAC receptors on intestinal epithelium, activating adenylyl cyclase and raising cAMP. This stimulates active Cl- secretion and inhibits Na+ absorption, causing profuse secretory (watery) diarrhoea unresponsive to fasting. VIPoma syndrome (WDHA): Watery Diarrhoea, Hypokalaemia, Achlorhydria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','hard','mcq','Glucagonoma presents with a characteristic skin rash. This rash is called:','["A. Erythema chronicum migrans","B. Necrolytic migratory erythema","C. Erythema marginatum","D. Erythema nodosum"]','D','Necrolytic migratory erythema (NME) is pathognomonic of glucagonoma. It is a blistering, crusting, migrating erythematous rash affecting the perineum, lower abdomen, and extremities. Pathogenesis: glucagon-driven catabolic state causing amino acid deficiency, zinc deficiency, and essential fatty acid depletion. Other features: hyperglycaemia, weight loss, anaemia, DVT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','easy','mcq','The majority of pancreatic neuroendocrine tumours (PNETs) are non-functional. The most sensitive marker for their detection is:','["A. Serum insulin","B. Chromogranin A (CgA) — a secretory granule protein","C. Urinary 5-HIAA","D. Serum gastrin"]','A','Chromogranin A (CgA) is a secretory granule acidic protein released by neuroendocrine cells. It is elevated in >80% of PNETs (functional and non-functional) and is the best general neuroendocrine tumour marker. It is also useful for monitoring treatment response. Synaptophysin is another immunohistochemical marker.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','mcq','Histologically, pancreatic neuroendocrine tumours show:','["A. Glandular structures with mucin secretion","B. Organoid nesting, trabecular, or gyriform patterns with uniform cells and salt-and-pepper chromatin","C. Signet ring cells and mucinous stroma","D. Squamous differentiation with keratin pearls"]','B','PNETs (carcinoid-like histology) show: organoid nesting, trabecular, gyriform, or solid growth patterns. Cells are uniform with round nuclei, ''''salt-and-pepper'''' (finely stippled) chromatin (a feature of neuroendocrine chromatin pattern), and moderate amphophilic cytoplasm. Immunostaining: synaptophysin+, chromogranin A+, CD56+.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','mcq','The majority of gastrinomas (~60-70%) occur in the ''''gastrinoma triangle,'''' which is bounded by:','["A. Hepatic flexure, splenic flexure, and pancreatic tail","B. Junction of cystic and common bile duct, junction of 2nd and 3rd duodenum, and junction of head/neck of pancreas","C. Portal vein, superior mesenteric artery, and inferior mesenteric vein","D. Hepatic artery, gastroduodenal artery, and right gastric artery"]','C','The gastrinoma triangle (Passaro''''s triangle): bounded by (1) junction of cystic duct and CBD superiorly, (2) junction of 2nd and 3rd parts of duodenum inferiorly, and (3) junction of pancreatic head and neck medially. ~60-70% of gastrinomas (including duodenal wall gastrinomas) occur in this region.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','hard','mcq','Somatostatinoma of the pancreas causes a triad of:','["A. Hypoglycaemia, diarrhoea, and skin rash","B. Diabetes mellitus, cholelithiasis (gallstones), and steatorrhoea","C. Profuse watery diarrhoea, hypokalaemia, and achlorhydria","D. Recurrent peptic ulcers, diarrhoea, and elevated gastrin"]','D','Somatostatinoma inhibitory triad: (1) Diabetes mellitus (somatostatin inhibits insulin and glucagon), (2) Cholelithiasis/gallstones (somatostatin inhibits CCK, reducing gallbladder emptying), (3) Steatorrhoea (somatostatin inhibits pancreatic enzyme secretion and reduces intestinal motility). Also: hypochlorhydria, diarrhoea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','medium','mcq','PPoma (pancreatic polypeptide-secreting tumour) is distinguished from other PNETs by:','["A. Causing severe hypoglycaemia","B. Being clinically silent (non-functional) — pancreatic polypeptide has no significant systemic hormonal effect","C. Secreting multiple hormones simultaneously","D. Being exclusively malignant"]','A','PPomas (pancreatic polypeptide-secreting tumours) are among the ''''non-functional'''' PNETs — elevated PP levels cause no specific clinical syndrome. They are detected incidentally or by mass effect. Elevated serum PP may be a marker. They can be large before presentation and may be malignant (liver metastases common).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Endocrine Pancreas Tumours','easy','mcq','The ki-67 proliferation index is used to grade pancreatic neuroendocrine tumours. G3 tumours (high-grade) have a ki-67 index of:','["A. <2%","B. 3-20%","C. >20%","D. >50% exclusively"]','B','WHO 2019 grading of PNETs: G1 = ki-67 <3% and <2 mitoses/2mm²; G2 = ki-67 3-20% or 2-20 mitoses/2mm²; G3 (well-differentiated NET) = ki-67 >20%; Poorly differentiated neuroendocrine carcinoma (NEC) = ki-67 typically >55%, highly aggressive. G3 NETs can have variable behaviour unlike NEC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','easy','mcq','MEN 1 (Wermer syndrome) is caused by mutation of which tumour suppressor gene?','["A. RET proto-oncogene on chromosome 10q11","B. MENIN gene on chromosome 11q13","C. VHL gene on chromosome 3p25","D. RB1 gene on chromosome 13q14"]','A','MEN 1 is caused by loss-of-function (tumour suppressor) mutations in the MENIN gene on chromosome 11q13. Menin is a scaffolding protein involved in histone methylation (MLL complex), transcription regulation, and DNA repair. It functions as a classical tumour suppressor (two-hit model): germline + somatic second hit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','mcq','The most common and earliest manifestation of MEN 1 is:','["A. Prolactinoma","B. Gastrinoma","C. Primary hyperparathyroidism","D. Insulinoma"]','B','Primary hyperparathyroidism (parathyroid adenoma/hyperplasia) occurs in >90% of MEN 1 patients and is usually the first manifestation, presenting in the 3rd-4th decade. It involves all four glands (multiglandular disease), unlike the solitary adenoma of sporadic hyperparathyroidism. Biochemical screening (calcium/PTH) detects it early.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','mcq','MEN 2A (Sipple syndrome) consists of which combination?','["A. Medullary thyroid carcinoma, phaeochromocytoma, and primary hyperparathyroidism","B. Medullary thyroid carcinoma, phaeochromocytoma, and marfanoid habitus/mucosal neuromas","C. Parathyroid adenoma, pituitary adenoma, and pancreatic islet tumour","D. Papillary thyroid carcinoma, parathyroid hyperplasia, and phaeochromocytoma"]','C','MEN 2A (Sipple syndrome): (1) Medullary thyroid carcinoma (virtually 100% — most common and first manifestation), (2) Phaeochromocytoma (~50%, bilateral), (3) Primary hyperparathyroidism (~20%). All caused by activating germline RET mutations (most commonly codon 634, exon 11).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','hard','mcq','MEN 2B differs from MEN 2A by the additional presence of:','["A. Parathyroid hyperplasia and hypercalcaemia","B. Marfanoid body habitus, mucosal neuromas, and ganglioneuromatosis of the GI tract","C. Cutaneous lipomas and facial angiofibromas","D. Parathyroid carcinoma and multiple pituitary adenomas"]','D','MEN 2B: (1) MTC (nearly 100%, most aggressive form), (2) Phaeochromocytoma (~50%), (3) Marfanoid habitus, (4) Mucosal neuromas (lips, tongue, eyelids — bumpy lips sign), (5) GI ganglioneuromatosis causing constipation/megacolon. Unlike MEN 2A: NO parathyroid disease. MEN 2B RET mutation: codon 918 (exon 16) — most aggressive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','easy','mcq','The RET proto-oncogene encodes:','["A. A nuclear transcription factor regulating cell growth","B. A receptor tyrosine kinase activated by GDNF family ligands","C. A G-protein alpha subunit regulating adenylyl cyclase","D. A tumour suppressor protein involved in DNA repair"]','A','RET (REarranged during Transfection) encodes a transmembrane receptor tyrosine kinase. It is activated by GDNF (glial cell line-derived neurotrophic factor) family ligands. Activating RET mutations cause MEN 2A, MEN 2B, and familial MTC. Loss-of-function RET mutations cause Hirschsprung disease. RET/PTC rearrangements drive papillary thyroid carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','mcq','A patient with MEN 2A should have prophylactic thyroidectomy performed:','["A. Only after calcitonin levels begin rising","B. Based on the specific RET codon mutation (risk category stratification), as early as infancy for highest-risk mutations","C. Only if ultrasound shows a thyroid nodule","D. At age 40 regardless of mutation type"]','B','Prophylactic thyroidectomy timing in MEN 2 is stratified by RET codon mutation risk: Highest risk (codon 918/M918T = MEN 2B) — within first 6 months of life; High risk (codon 634, 883) — by age 5; Moderate risk (codons 609,611,618,620,630,768,790,791,804,891) — consider by age 5-10 or based on calcitonin. This prevents inevitable MTC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','mcq','Carney complex is a related MEN-like syndrome caused by mutation in PRKAR1A gene, manifesting with:','["A. Skin pigmentation (lentigines), myxomas, and endocrine overactivity (primary pigmented nodular adrenocortical disease)","B. Parathyroid hyperplasia, MTC, and phaeochromocytoma","C. Lipomas, angiofibromas, and pituitary GH adenoma","D. Café-au-lait macules, neurofibromas, and optic gliomas"]','C','Carney complex (PRKAR1A mutation — regulatory subunit of PKA): (1) spotty skin pigmentation (lentigines, blue naevi), (2) cardiac and extra-cardiac myxomas, (3) primary pigmented nodular adrenocortical disease (PPNAD) — bilateral micronodular Cushing syndrome, (4) testicular tumours (large cell calcifying Sertoli cell), (5) pituitary GH adenoma. Distinct from MEN syndromes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','hard','mcq','In MEN 1, the pancreatic tumour causing the highest morbidity/mortality is:','["A. Insulinoma","B. Gastrinoma (Zollinger-Ellison syndrome)","C. Glucagonoma","D. PPoma"]','D','Gastrinoma is the most clinically significant pancreatic tumour in MEN 1, causing Zollinger-Ellison syndrome with severe peptic ulcer disease, diarrhoea, and malnutrition. In MEN 1, gastrinomas are characteristically multiple, small, and duodenal (>50%). They are the leading cause of morbidity and mortality in MEN 1 after parathyroid disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','medium','mcq','The ''''5-3-1 rule'''' of MEN 1 screening recommends biochemical surveillance for parathyroid disease from age:','["A. 50","B. 30","C. 10","D. 5"]','A','Biochemical screening for MEN 1 gene carriers should begin by age 5 for insulinoma (which can occur in childhood), by age 8 for other tumours. Comprehensive guidelines recommend screening from age 5 with calcium/PTH (parathyroid), fasting glucose/insulin (insulinoma), gastrin (gastrinoma), and prolactin/IGF-1 (pituitary) annually or biannually.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Pathology','Multiple Endocrine Neoplasia','easy','mcq','Familial medullary thyroid carcinoma (FMTC) is distinguished from MEN 2A by:','["A. More aggressive behaviour and earlier onset","B. Occurrence of MTC alone without phaeochromocytoma or hyperparathyroidism in at least 4 affected family members","C. Different RET mutation spectrum (only exon 16 mutations)","D. Autosomal recessive inheritance"]','B','FMTC is diagnosed when a family has 4+ affected members with MTC and NO phaeochromocytoma or hyperparathyroidism across generations. It is now considered a variant/subtype of MEN 2A with very low penetrance of non-thyroid features. RET mutations are similar to MEN 2A (codons 609,618,620,634, exon 8,10,11). Autosomal dominant inheritance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
